-- The catalog API's read surface: the `uga` schema (views over the registrar tables and the
-- scrape run log) and the full-text search index on courses. Generated by
-- `supabase db schema declarative sync --no-apply` from supabase/schemas, so the migration
-- history and the tree agree (supabase/README.md). The role that reads these is created in
-- migration 62.

CREATE SCHEMA "uga";

CREATE TABLE "uga"."scrapeRuns" (
  "id"         bigint                   GENERATED ALWAYS AS IDENTITY NOT NULL,
  "job"        text                     NOT NULL,
  "startedAt"  timestamp with time zone NOT NULL,
  "finishedAt" timestamp with time zone NOT NULL DEFAULT now(),
  "ok"         boolean                  NOT NULL,
  "report"     jsonb                    NOT NULL,
  CONSTRAINT "scrapeRuns_job_nonempty" CHECK ((btrim(job) <> ''::text)),
  CONSTRAINT "scrapeRuns_pkey" PRIMARY KEY (id)
);

ALTER TABLE "uga"."scrapeRuns"
  ENABLE ROW LEVEL SECURITY;

CREATE VIEW "uga"."buildings" AS  SELECT id,
    description,
    address,
    latitude,
    longitude
   FROM schedule_builder.buildings b;

CREATE VIEW "uga"."campuses" AS  SELECT id,
    abbr,
    description
   FROM schedule_builder.campuses c;

CREATE VIEW "uga"."colleges" AS  SELECT id,
    description
   FROM schedule_builder.colleges c;

CREATE VIEW "uga"."courseDetails" AS  SELECT "courseId",
    description,
    "gradingSystem",
    "semesterOffered",
    corequisite,
    "equivalentCourses",
    prerequisites,
    "lastFetched"
   FROM schedule_builder."courseDetails" d;

CREATE VIEW "uga"."courses" AS  SELECT id,
    abbr,
    title,
    "abbrTitle",
    "courseNumber",
    "minCreditHours",
    "maxCreditHours",
    "minBillingCreditHours",
    honors,
    "collegeId",
    "departmentId",
    "subjectId",
    to_tsvector('english'::regconfig, (((((abbr)::text || ' '::text) || regexp_replace((abbr)::text, '^([A-Za-z]+)([0-9])'::text, '\1 \2'::text)) || ' '::text) || (title)::text)) AS "searchDocument"
   FROM schedule_builder.courses c;

CREATE VIEW "uga"."departments" AS  SELECT id,
    description,
    "collegeId"
   FROM schedule_builder.departments d;

CREATE VIEW "uga"."instructors" AS  SELECT id,
    "firstName",
    "lastName"
   FROM schedule_builder.instructors i;

CREATE VIEW "uga"."meetings" AS  SELECT id,
    "academicPeriod",
    "offeringCrn",
    monday,
    tuesday,
    wednesday,
    thursday,
    friday,
    saturday,
    sunday,
    "startDate",
    "endDate",
    "startTime",
    "endTime",
    "buildingId",
    room,
    "locationStatus"
   FROM schedule_builder.meetings m;

CREATE VIEW "uga"."offerings" AS  SELECT crn,
    "academicPeriod",
    "partOfTerm",
    "courseId",
    "instructorId",
    "campusId",
    "scheduleTypeId",
    "maximumEnrollment",
    "actualEnrollment",
    "seatsAvailable",
    cancelled,
    "lastSeenAt"
   FROM schedule_builder.offerings o;

CREATE VIEW "uga"."partsOfTerm" AS  SELECT "academicPeriod",
    code,
    description,
    "classesBegin",
    "dropAddEnds",
    "censusDate",
    "withdrawalDeadline",
    "classesEnd",
    "finalsEnd"
   FROM schedule_builder."partsOfTerm" p;

CREATE VIEW "uga"."subjects" AS  SELECT id,
    abbr,
    description
   FROM schedule_builder.subjects s;

CREATE VIEW "uga"."terms" AS  SELECT "academicPeriod",
    description,
    (EXISTS ( SELECT 1
           FROM schedule_builder.offerings o
          WHERE ((o."academicPeriod" = t."academicPeriod") AND (o.cancelled = false)))) AS available
   FROM schedule_builder.terms t;

CREATE INDEX courses_search_idx ON schedule_builder.courses
  USING gin
  (to_tsvector('english'::regconfig, (((((abbr)::text || ' '::text) || regexp_replace((abbr)::text, '^([A-Za-z]+)([0-9])'::text, '\1 \2'::text)) || ' '::text) || (title)::text)));

CREATE INDEX "scrapeRuns_job_finishedAt_idx" ON uga."scrapeRuns" USING btree (job, "finishedAt" DESC);

COMMENT ON SCHEMA "uga" IS 'UGA reference data as the catalog API reads it: views over the registrar tables, readable by every role because the data is already public, and the scrape run log, which is not. The catalog Worker reads as the catalog_reader role, which holds nothing else. Not exposed through PostgREST.';

COMMENT ON TABLE "uga"."scrapeRuns" IS 'One row per finished scrape run: whether every invariant held, and the per-term report (counts, invariants, building coverage). The job heartbeat is written only when ok is true.';

COMMENT ON VIEW "uga"."terms" IS 'Every term, with whether any section is still offered. The catalog lists only available terms.';

GRANT USAGE ON SCHEMA "uga" TO PUBLIC;

GRANT CREATE, USAGE ON SCHEMA "uga" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "uga"."scrapeRuns" TO "postgres", "service_role";

GRANT SELECT ON TABLE "uga"."buildings" TO PUBLIC;

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "uga"."buildings" TO "postgres";

