GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "uga"."offerings" TO "postgres";

GRANT SELECT ON TABLE "uga"."partsOfTerm" TO PUBLIC;

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "uga"."partsOfTerm" TO "postgres";

GRANT SELECT ON TABLE "uga"."subjects" TO PUBLIC;

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "uga"."subjects" TO "postgres";

GRANT SELECT ON TABLE "uga"."terms" TO PUBLIC;

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "uga"."terms" TO "postgres";
